    Bug 2027673 - After upgrade to version 149 the week (and day) view of the calendar is showing the date and time axis swapped. r=vineet

    Migrate persisted values for these:
    https://searchfox.org/comm-central/rev/53d7fc8aeb021d162b914ccb74418ae72515d812/calendar/base/content/calendar-commands.inc.xhtml#76-79

    Differential Revision: https://phabricator.services.mozilla.com/D291676

diff --git a/mail/modules/MailMigrator.sys.mjs b/mail/modules/MailMigrator.sys.mjs
index 79bf3ae8eb5..81d16c72135 100644
--- a/mail/modules/MailMigrator.sys.mjs
+++ b/mail/modules/MailMigrator.sys.mjs
@@ -30,7 +30,7 @@ export var MailMigrator = {
   _migrateUI() {
     // The code for this was ported from
     // mozilla/browser/components/nsBrowserGlue.js
-    const UI_VERSION = 59;
+    const UI_VERSION = 60;
     const UI_VERSION_PREF = "mail.ui-rdf.version";
     let currentUIVersion = Services.prefs.getIntPref(UI_VERSION_PREF, 0);

@@ -429,6 +429,36 @@ export var MailMigrator = {
         }
       }

+      if (currentUIVersion < 60) {
+        function updateCheckedValue(url, id) {
+          if (Services.xulStore.hasValue(url, id, "checked")) {
+            const oldValue = Services.xulStore.getValue(url, id, "checked");
+            Services.xulStore.setValue(
+              url,
+              id,
+              "checked",
+              oldValue == "false" ? "-moz-missing\n" : ""
+            );
+          }
+        }
+        updateCheckedValue(
+          "chrome://messenger/content/messenger.xhtml",
+          "calendar_toggle_orientation_command"
+        );
+        updateCheckedValue(
+          "chrome://messenger/content/messenger.xhtml",
+          "calendar_toggle_workdays_only_command"
+        );
+        updateCheckedValue(
+          "chrome://messenger/content/messenger.xhtml",
+          "calendar_toggle_tasks_in_view_command"
+        );
+        updateCheckedValue(
+          "chrome://messenger/content/messenger.xhtml",
+          "calendar_toggle_show_completed_in_view_command"
+        );
+      }
+
       // Migration tasks that may take a long time are not run immediately, but
       // added to the MigrationTasks object then run at the end.
       //
